import base from './playwright.config';
const servers=Array.isArray(base.webServer)?base.webServer:base.webServer?[base.webServer]:[];
export default {...base,workers:1,reporter:[['list']],outputDir:'test-results/browser-isolated',webServer:servers.map(server=>({...server,command:server.command?.replace('npm run dev:ui -- ','npm run dev:ui -- --config vite.browser-isolated.local.ts ').replace('npx vite build ','npx vite build --config vite.browser-isolated.local.ts ').replace('npx vite preview ','npx vite preview --config vite.browser-isolated.local.ts ')}))};
